import json
import os
import platform
import threading
from typing import Optional


class AHReportConfiguration:
    def __init__(self):
        self._lock = threading.Lock()
        self._app_version: str = '10.0.0'
        self._mcp_version: str = '10.0.0'
        self._app_id: str = '14'
        self._username: str = self._load_username_from_auth()
        self._is_report_data: bool = True
        self._user_agent: str = self._build_user_agent()
        self._ide_type: int = 300

    def _load_username_from_auth(self) -> str:
        auth_file = os.path.expanduser("~/.ahdev/auth.json")
        try:
            if os.path.exists(auth_file):
                with open(auth_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                    return data.get("username", "")
        except Exception:
            pass
        return ""

    def _build_user_agent(self) -> str:
        return f'{platform.system()} ({platform.machine()})'

    def set_app_version(self, value: str):
        with self._lock:
            self._app_version = value

    def get_app_version(self) -> str:
        with self._lock:
            return self._app_version

    def set_app_id(self, value: str):
        with self._lock:
            self._app_id = value

    def get_app_id(self) -> str:
        with self._lock:
            return self._app_id

    def set_username(self, value: str):
        with self._lock:
            self._username = value

    def get_username(self) -> str:
        with self._lock:
            return self._username

    def set_is_report_code(self, value: bool):
        with self._lock:
            self._is_report_data = value

    def get_is_report_code(self) -> bool:
        with self._lock:
            return self._is_report_data

    def set_user_agent(self, value: str):
        with self._lock:
            self._user_agent = value

    def get_user_agent(self) -> str:
        with self._lock:
            return self._user_agent

    def set_mcp_version(self, value: str):
        with self._lock:
            self._mcp_version = value

    def get_mcp_version(self) -> str:
        with self._lock:
            return self._mcp_version

    def set_ide_type(self, value: int):
        with self._lock:
            self._ide_type = value

    def get_ide_type(self) -> int:
        with self._lock:
            return self._ide_type
